message:
Running command: bash /workspace/build.sh 'cd /gt/_work/src && cat > /tmp/test_mqtt.c << "EOF"
#include <stdio.h>
#include <string.h>
#define MG_ENABLE_SOCKET 0
#define MG_ENABLE_LOG 0
#define MG_ENABLE_LINES 1
#define MG_ENABLE_TCPIP 1
#define MG_IO_SIZE (32 * 1024 * 1024)
#include "mongoose.c"

int main() {
  uint8_t data[] = {0x30, 0x08, 0x00, 0x01, 0x61, 0x80, 0x80, 0x80, 0x00};
  struct mg_mqtt_message mm;
  int rc = mg_mqtt_parse(data, sizeof(data), 5, &mm);
  printf("rc=%d MQTT_OK=%d\n", rc, MQTT_OK);
  printf("dgram.len=%zu props_start=%zu props_size=%zu\n", mm.dgram.len, mm.props_start, mm.props_size);
  printf("dgram.buf=%p data=%p\n", mm.dgram.buf, data);
  if (rc == MQTT_OK) {
    struct mg_mqtt_prop prop;
    size_t ofs = 0;
    ofs = mg_mqtt_next_prop(&mm, &prop, ofs);
    printf("next_prop returned ofs=%zu\n", ofs);
  }
  return 0;
}
EOF
gcc -g -fsanitize=address -I. /tmp/test_mqtt.c -o /tmp/test_mqtt 2>&1 | tail -5 && /tmp/test_mqtt 2>&1 | head -30'

